import { Avatar as BaseAvatar } from "@base-ui/react/avatar";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/avatar.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

export type AvatarSize = "sm" | "md" | "lg";

export interface AvatarProps extends StaticClass<typeof BaseAvatar.Root> {
  size?: AvatarSize;
}

/**
 * Round user image with a fallback. The image loads in the background, and the
 * fallback (initials) shows until it is ready or if it fails.
 *
 * @example
 * <Avatar>
 *   <AvatarImage src={user.photo} alt={user.name} />
 *   <AvatarFallback>{initials(user.name)}</AvatarFallback>
 * </Avatar>
 */
export function Avatar({ size = "md", className, ...props }: AvatarProps) {
  return <BaseAvatar.Root className={cn("eui-avatar", `eui-avatar--${size}`, className)} {...props} />;
}

export function AvatarImage({ className, ...props }: StaticClass<typeof BaseAvatar.Image>) {
  return <BaseAvatar.Image className={cn("eui-avatar__image", className)} {...props} />;
}

export function AvatarFallback({ className, ...props }: StaticClass<typeof BaseAvatar.Fallback>) {
  return <BaseAvatar.Fallback className={cn("eui-avatar__fallback", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Avatar. Neutral by default; the fallback uses the hover surface so it stays calm. */

.eui-avatar {
  --eui-avatar-size: 32px;
  --eui-avatar-fs: 12px;

  position: relative;
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--eui-avatar-size);
  height: var(--eui-avatar-size);
  overflow: hidden;
  border-radius: var(--eui-radius-full);
  background-color: var(--eui-color-hover);
  color: var(--eui-color-fg-muted);
  font-size: var(--eui-avatar-fs);
  font-weight: 500;
  letter-spacing: 0.02em;
  user-select: none;
}

.eui-avatar--sm {
  --eui-avatar-size: 24px;
  --eui-avatar-fs: 10px;
}
.eui-avatar--md {
  --eui-avatar-size: 32px;
  --eui-avatar-fs: 12px;
}
.eui-avatar--lg {
  --eui-avatar-size: 48px;
  --eui-avatar-fs: 16px;
}

.eui-avatar::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 var(--eui-border-width) var(--eui-color-border);
  pointer-events: none;
}

.eui-avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.eui-avatar__fallback {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}
